  assert e['kind'] in {'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
  assert e['unit'] in {'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
  for field,xml in [('source_quote',src['source_xml']),('proposed_quote',out['proposed_xml'])]:
   if not (len(e[field])>=12 and e[field] in plain(xml)): failures.append((n,e['measure_id'],field,e[field]))
 checks=out['reference_checks']; assert len(checks)==len(r['requirements'][key])
 assert {c['target_key'] for c in checks}==set(r['requirements'][key])
 for c in checks:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'],(n,c['target_key'])
  assert len(c['assessment'])>=80
 for xml in [src['source_xml'],out['proposed_xml'] or '']:
  q=Text();q.feed(xml)
  assert 'table' not in q.tags
 assert len(out['reason'])>40 and len(out['review_notes'])>40
print('quote_failures',json.dumps(failures,ensure_ascii=False))
assert not failures
print('articles',len(a),'reference_checks',sum(len(o['reference_checks']) for o in a),'effects',sum(len(o['substantive_impact']['effects']) for o in a))
print('statuses',dict(Counter(o['status'] for o in a)))
print('classifications',dict(Counter(o['substantive_impact']['classification'] for o in a)))
print('current L1235-3-1',r['targets']['LEGITEXT000006072050|LEGIARTI000036762026']['view_sha256'])
